import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {lstatSync,readFileSync,writeFileSync} from 'node:fs';
import {assertProvider,assertOwned} from './questionnaire-handover-owned-release-20261016.mjs';
import {PRESERVED_CURRENT_RUNTIME,canonicalAcceptedRuntimeMetadata as canonicalHqEvidence,acceptedRuntimeMetadataDigest as hqEvidenceDigest,assertRecordedWeekCurrentReceipt,assertRecordedWeekCurrentRun,readRecordedWeekCurrentWitness} from './accepted-current-runtime-starting-point-20261017.mjs';
import {currentRuntimePreservationHistoricalView} from './current-runtime-preservation-20261016.mjs';
import {createGithubProofReader} from './github-proof-get.mjs';

export const RETAINED_ACCEPTED_HQ_KIND='retained_accepted_hq_runtime';
const repository='shiftsometimber/shift-core',repositoryId=1328867509,workflow='.github/workflows/hq-management-release.yml';
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
export {canonicalHqEvidence,hqEvidenceDigest};
const time=value=>{assert.equal(typeof value,'string');const n=Date.parse(value);assert(Number.isFinite(n),'Valid original release time required');return n;};
const regular=(path,max)=>{const s=lstatSync(path);assert(s.isFile()&&!s.isSymbolicLink()&&s.size>0&&s.size<=max);return readFileSync(path);};
const git=(...args)=>execFileSync('/usr/bin/git',['--no-replace-objects','--no-optional-locks',...args],{encoding:'utf8',maxBuffer:64e6}).trim();
const successful=(job,name)=>{const rows=job.steps.filter(step=>step.name===name);assert.equal(rows.length,1,'One original required HQ step: '+name);assert.equal(rows[0].status,'completed');assert.equal(rows[0].conclusion,'success','Required HQ step did not pass: '+name);return rows[0];};
const identity=d=>({id:d.id,versions:d.versions,created_on:d.created_on,annotations:d.annotations});
export function acceptedHqSpec(bytes=readRecordedWeekCurrentWitness()){
 const receipt=assertRecordedWeekCurrentReceipt(bytes);return {receipt,hq:receipt.workers.hq,settingsSha256:receipt.settingsSha256.hq};
}
export function assertAcceptedHqSnapshot({deployment,version,bundle,settings},candidate,bytes=readRecordedWeekCurrentWitness()){
 const {hq,settingsSha256}=acceptedHqSpec(bytes);assert(Buffer.isBuffer(bundle));assert(candidate&&typeof candidate==='object');assert.match(candidate.source||'',/^[a-f0-9]{40}$/);
 assertProvider({deployment,version},{deployment:hq.deploymentId,version:hq.versionId,gpEnabled:true},{hq:true});assertOwned(deployment,hq,hq.source,hq.run,hq.attempt);
 assert.equal(hqEvidenceDigest(version.resources.bindings.slice().sort((a,b)=>a.name.localeCompare(b.name))),hq.allBindingsSha256,'Every actual accepted HQ binding must remain exact');
 assert.equal(bundle.length,hq.bundleBytes,'Accepted HQ bundle length changed');assert.equal(sha(bundle),hq.bundleSha256,'Accepted HQ bundle bytes changed');assert.equal(candidate.bytes,bundle.length);assert.equal(candidate.sha256,sha(bundle),'Current compiled HQ code differs from accepted serving code');
 assert.equal(hqEvidenceDigest(settings),settingsSha256,'Actual accepted HQ settings changed');assert.equal(settings.observability?.redact_query_string,true,'Original query-string privacy control must remain on');
 return {kind:RETAINED_ACCEPTED_HQ_KIND,runtimeSource:hq.source,runtimeRun:hq.run,runtimeAttempt:hq.attempt,deploymentId:deployment.id,versionId:version.id,bundleSha256:sha(bundle),bundleBytes:bundle.length,allBindingsSha256:hq.allBindingsSha256,privacySettingsSha256:settingsSha256,gpEnabled:true,partnersEnabled:true,clinicalContractActivated:false,genuineHqHolderAcceptance:false,featureAcceptance:false,providerWrites:0,trafficWrites:0,dataWrites:0,externalMessages:0};
}
export function assertOriginalHqAcceptance(run,job,bytes=readRecordedWeekCurrentWitness()){
 const {hq}=acceptedHqSpec(bytes);assert.equal(run.id,hq.run);assert.equal(run.run_attempt,hq.attempt);assert.equal(run.head_sha,hq.source);assert.equal(run.head_branch,'release/gp-priority-direct-activation-20261016');assert.equal(run.path,'.github/workflows/gp-priority-direct-activation-20261016.yml');assert.equal(run.event,'push');assert.equal(run.status,'completed');assert.equal(run.conclusion,'success');
 for(const key of ['repository','head_repository']){assert.equal(run[key].id,repositoryId);assert.equal(run[key].full_name,repository);}
 assert.equal(job.id,117219963160);assert.equal(job.run_id,hq.run);assert.equal(job.run_attempt,hq.attempt);assert.equal(job.head_sha,hq.source);assert.equal(job.head_branch,run.head_branch);assert.equal(job.name,'release');assert.equal(job.status,'completed');assert.equal(job.conclusion,'success');assert(time(job.started_at)>=time(run.run_started_at));assert(time(job.completed_at)>=time(job.started_at));
 for(const name of ['Verify actual activation source, all original activation controls and owned provider guards','Verify both GP ON uploads and the unchanged accepted whole bundles before traffic','Activate only the exact prepared GP directory versions','Verify actual directory readiness, owned GP ON providers and all other controls'])successful(job,name);
 return {source:hq.source,run:hq.run,attempt:hq.attempt,job:job.id};
}
export function assertHqRetentionRunContext({source,runId,attempt,run,job,verifyJob,main,workflowRef},now){
 assert.match(source||'',/^[a-f0-9]{40}$/);assert.equal(main,source,'HQ proof requires actual current main');assert(Number.isSafeInteger(runId)&&runId>0);assert(Number.isSafeInteger(attempt)&&attempt>0);assert.equal(workflowRef,repository+'/'+workflow+'@refs/heads/main');
 assert.equal(run.id,runId);assert.equal(run.run_attempt,attempt);assert.equal(run.head_sha,source);assert.equal(run.head_branch,'main');assert.equal(run.path,workflow);assert.equal(run.name,'HQ Management Release');assert.equal(run.event,'push');assert.equal(run.status,'in_progress');assert.equal(run.conclusion,null);
 for(const key of ['repository','head_repository']){assert.equal(run[key].id,repositoryId);assert.equal(run[key].full_name,repository);}
 for(const [entry,name,status,conclusion]of[[job,'deploy','in_progress',null],[verifyJob,'verify','completed','success']]){assert(Number.isSafeInteger(entry.id)&&entry.id>0);assert.equal(entry.run_id,runId);assert.equal(entry.run_attempt,attempt);assert.equal(entry.head_sha,source);assert.equal(entry.head_branch,'main');assert.equal(entry.name,name);assert.equal(entry.status,status);assert.equal(entry.conclusion,conclusion);}
 assert.equal(job.completed_at,null);assert(time(job.started_at)>=time(run.run_started_at));const age=time(now)-time(job.started_at);assert(age>=0&&age<=15*60000,'Original15-minute HQ job limit still applies');assert(time(verifyJob.completed_at)<=time(job.started_at));
 for(const name of ['Run node hq-management-release-gate.mjs','Run node hq-management-gateway-acceptance.mjs','Run node --test tests/hq-commerce-content-v1.test.mjs tests/hq-catalogue-v1.test.mjs','Run npx wrangler deploy --config wrangler.hq-management.jsonc --dry-run --outdir /tmp/hq-build'])successful(verifyJob,name);
 for(const name of ['Require current main and approved payload','Capture unchanged public runtime and responses']){const step=successful(job,name);assert(time(step.completed_at)>=time(job.started_at));assert(time(step.completed_at)<=time(now));}
 return {source,run:runId,attempt,job:job.id,jobStartedAt:job.started_at,checkedAt:now};
}
function actualCandidate(){const candidate=JSON.parse(regular('b1-runtime-release/combined-hq-candidate.json',16384));const bundle=regular('b1-runtime-release/hq-candidate-build/hq-management-entry.js',32e6);assert.equal(candidate.bytes,bundle.length);assert.equal(candidate.sha256,sha(bundle),'Actual compiled candidate file changed');assert.equal(candidate.source,git('rev-parse','HEAD'));return {candidate,bundle};}
async function genuineContext(){
 const env=process.env;assert.equal(env.GITHUB_ACTIONS,'true');assert.equal(env.GITHUB_REPOSITORY,repository);assert.equal(env.GITHUB_REPOSITORY_ID,String(repositoryId));assert.equal(env.GITHUB_REF,'refs/heads/main');assert.equal(env.GITHUB_JOB,'deploy');const source=git('rev-parse','HEAD');assert.equal(source,env.GITHUB_SHA);
 const current=currentRuntimePreservationHistoricalView();assert.notEqual(current.head,current.rawHead,'Only the exact current preservation record may retain accepted HQ');assert.equal(current.rawHead,source);const sourceRecord=JSON.parse(execFileSync('/usr/bin/git',['show',source+':release/approved-runtime-composition.json'],{encoding:'utf8'})).currentRuntimePreservation20261016;assert.equal(sourceRecord.runtimeSource,PRESERVED_CURRENT_RUNTIME.source);
 const proof=createGithubProofReader({token:env.GH_TOKEN||env.GITHUB_TOKEN}),runId=Number(env.GITHUB_RUN_ID),attempt=Number(env.GITHUB_RUN_ATTEMPT),bytes=readRecordedWeekCurrentWitness(),{hq}=acceptedHqSpec(bytes);
 try{
  const [run,jobs,main,wrun,wjob,hrun,hjob]=await Promise.all([proof.get('/actions/runs/'+runId+'/attempts/'+attempt),proof.get('/actions/runs/'+runId+'/attempts/'+attempt+'/jobs?per_page=100'),proof.get('/git/refs/heads/main'),proof.get('/actions/runs/'+PRESERVED_CURRENT_RUNTIME.run+'/attempts/'+PRESERVED_CURRENT_RUNTIME.attempt),proof.get('/actions/jobs/'+PRESERVED_CURRENT_RUNTIME.job),proof.get('/actions/runs/'+hq.run+'/attempts/'+hq.attempt),proof.get('/actions/jobs/117219963160')]);
  assertRecordedWeekCurrentRun(wrun,wjob);assertOriginalHqAcceptance(hrun,hjob,bytes);assert.equal(jobs.total_count,jobs.jobs.length);const deploy=jobs.jobs.filter(j=>j.name==='deploy'),verify=jobs.jobs.filter(j=>j.name==='verify');assert.equal(deploy.length,1);assert.equal(verify.length,1);
  const now=new Date().toISOString(),context=assertHqRetentionRunContext({source,runId,attempt,run,job:deploy[0],verifyJob:verify[0],main:main.object?.sha,workflowRef:env.GITHUB_WORKFLOW_REF},now);assert.equal((await proof.get('/git/refs/heads/main')).object?.sha,source);current.assertCurrent();assert.equal(git('rev-parse','HEAD'),source);return {context,bytes,current};
 }catch(error){current.assertCurrent();throw error;}
}
async function providerRead(accountId,token,path,fetchImpl=fetch){assert.match(accountId||'',/^[a-f0-9]{32}$/);assert(typeof token==='string'&&token.length);const r=await fetchImpl('https://api.cloudflare.com/client/v4/accounts/'+accountId+'/workers/scripts/shift-hq-management'+path,{method:'GET',headers:{Authorization:'Bearer '+token},signal:AbortSignal.timeout(30000)});assert(r.ok,'Read-only accepted HQ evidence unavailable: '+r.status);return r;}
async function providerValue(accountId,token,path,fetchImpl){const body=await(await providerRead(accountId,token,path,fetchImpl)).json();assert.equal(body.success,true);return body.result;}
async function active(accountId,token,fetchImpl){const value=await providerValue(accountId,token,'/deployments',fetchImpl);assert(Array.isArray(value.deployments)&&value.deployments.length);return value.deployments.toSorted((a,b)=>Date.parse(b.created_on)-Date.parse(a.created_on))[0];}
async function snapshot(accountId,token,fetchImpl){
 const {hq}=acceptedHqSpec();const deployment=await active(accountId,token,fetchImpl);assert.equal(deployment.id,hq.deploymentId,'Unknown HQ runtime refuses retention before bundle reads');assert.deepEqual(deployment.versions,[{version_id:hq.versionId,percentage:100}]);
 const [version,r,settings]=await Promise.all([providerValue(accountId,token,'/versions/'+hq.versionId,fetchImpl),providerRead(accountId,token,'/content/v2?version='+hq.versionId,fetchImpl),providerValue(accountId,token,'/script-settings',fetchImpl)]);assert(r.headers.get('content-type')?.startsWith('multipart/form-data'));const entry=r.headers.get('cf-entrypoint');assert.equal(entry,'hq-management-entry.js');const part=(await r.formData()).get(entry);assert(part&&typeof part.arrayBuffer==='function');const bundle=Buffer.from(await part.arrayBuffer());assert.deepEqual(identity(await active(accountId,token,fetchImpl)),identity(deployment),'HQ moved during read-only snapshot');return {deployment,version,bundle,settings};
}
export function assertRetainedHqReceipt(receipt,context,candidate,provider,bytes=readRecordedWeekCurrentWitness()){
 const expected=assertAcceptedHqSnapshot(provider,candidate,bytes);assert.equal(receipt.kind,RETAINED_ACCEPTED_HQ_KIND,'Unknown or altered retention receipt');assert.equal(receipt.source,expected.runtimeSource);assert.equal(receipt.run,expected.runtimeRun);assert.equal(receipt.attempt,expected.runtimeAttempt);assert.equal(receipt.proofSource,context.source);assert.equal(receipt.proofRun,context.run);assert.equal(receipt.proofAttempt,context.attempt);assert.equal(receipt.proofJob,context.job);assert.equal(receipt.deploymentId,expected.deploymentId);assert.equal(receipt.versionId,expected.versionId);assert.deepEqual(receipt.combinedHqCandidate,candidate);assert.equal(candidate.source,context.source);assert.equal(receipt.originalWitnessSHA256,PRESERVED_CURRENT_RUNTIME.receiptSHA256);assert.equal(receipt.originalReceiptAt,acceptedHqSpec(bytes).receipt.at);assert.equal(receipt.privacySettingsSha256,expected.privacySettingsSha256);assert.equal(receipt.allBindingsSha256,expected.allBindingsSha256);assert.equal(receipt.publicRuntimeChanged,false);for(const key of ['providerWrites','trafficWrites','dataWrites','externalMessages'])assert.equal(receipt[key],0);assert.equal(receipt.featureAcceptance,false);assert.equal(receipt.genuineHqHolderAcceptance,false);assert.deepEqual(identity(receipt.before),identity(provider.deployment));
 assert(time(receipt.at)>=time(context.jobStartedAt)&&time(receipt.at)<=time(context.checkedAt)+300000,'Retention proof time does not belong to this actual job');
 const exact={...expected,source:expected.runtimeSource,run:expected.runtimeRun,attempt:expected.runtimeAttempt,proofSource:context.source,proofRun:context.run,proofAttempt:context.attempt,proofJob:context.job,at:receipt.at,originalWitnessSHA256:PRESERVED_CURRENT_RUNTIME.receiptSHA256,originalReceiptAt:acceptedHqSpec(bytes).receipt.at,combinedHqCandidate:candidate,before:provider.deployment,publicRuntimeChanged:false};assert.deepEqual(receipt,exact,'Altered or extended HQ retention receipt');return expected;
}
export async function prepareAcceptedHqRetention(before,{accountId,token,fetchImpl=fetch}={}){
 const {context,bytes,current}=await genuineContext();const {candidate}=actualCandidate();assert.equal(candidate.source,context.source);const provider=await snapshot(accountId,token,fetchImpl);assert.deepEqual(identity(before),identity(provider.deployment),'Captured HQ predecessor changed');const accepted=assertAcceptedHqSnapshot(provider,candidate,bytes);current.assertCurrent();const {hq,receipt:original}=acceptedHqSpec(bytes);
 const receipt={...accepted,source:hq.source,run:hq.run,attempt:hq.attempt,proofSource:context.source,proofRun:context.run,proofAttempt:context.attempt,proofJob:context.job,at:new Date().toISOString(),originalWitnessSHA256:PRESERVED_CURRENT_RUNTIME.receiptSHA256,originalReceiptAt:original.at,combinedHqCandidate:candidate,before:provider.deployment,publicRuntimeChanged:false};assertRetainedHqReceipt(receipt,context,candidate,provider,bytes);writeFileSync('b1-runtime-release/combined-hq-starting-point.json',JSON.stringify(receipt,null,2)+'\n',{mode:0o600,flag:'wx'});return receipt;
}
export async function verifyAcceptedHqRetention(receipt,{accountId,token,fetchImpl=fetch,stage='after'}={}){
 assert(['before','after','rollback'].includes(stage));const {context,bytes,current}=await genuineContext();const {candidate}=actualCandidate(),provider=await snapshot(accountId,token,fetchImpl);const accepted=assertRetainedHqReceipt(receipt,context,candidate,provider,bytes);current.assertCurrent();const proof={at:new Date().toISOString(),stage,...accepted,proofSource:context.source,proofRun:context.run,proofAttempt:context.attempt,proofJob:context.job,action:stage==='rollback'?'no_owned_runtime_write_to_restore':'retained_runtime_reverified'};writeFileSync('b1-runtime-release/accepted-hq-retention-'+stage+'.json',JSON.stringify(proof,null,2)+'\n',{mode:0o600,flag:'wx'});return {proof,provider};
}
